# security_engine/detector_interfaces.py
"""
Interfaces for API security detectors.
"""

from __future__ import annotations
from abc import ABC, abstractmethod
from typing import List, Optional
from .event import APIEvent


class SecurityAlert:
    """Security alert generated by a detector."""
    
    def __init__(
        self,
        alert_id: str,
        alert_type: str,
        severity: str,
        description: str,
        detection_method: str,
        timestamp: str,
        related_event_ids: Optional[List[str]] = None,
        recommended_action: Optional[str] = None,
        confidence: Optional[float] = None,
    ):
        self.alert_id = alert_id
        self.alert_type = alert_type  # e.g., 'scraping', 'token_misuse', 'bola'
        self.severity = severity  # e.g., 'low', 'medium', 'high', 'critical'
        self.description = description
        self.detection_method = detection_method
        self.timestamp = timestamp  # ISO format
        self.related_event_ids = related_event_ids or []
        self.recommended_action = recommended_action
        self.confidence = confidence  # Optional, only when meaningfully supported

    def to_dict(self) -> dict:
        """Convert to dictionary matching the API spec."""
        result = {
            "alert_id": self.alert_id,
            "alert_type": self.alert_type,
            "severity": self.severity,
            "description": self.description,
            "detection_method": self.detection_method,
            "timestamp": self.timestamp,
        }
        if self.related_event_ids:
            result["related_event_ids"] = self.related_event_ids
        if self.recommended_action:
            result["recommended_action"] = self.recommended_action
        if self.confidence is not None:
            result["confidence"] = self.confidence
        return result

    @classmethod
    def from_dict(cls, data: dict) -> "SecurityAlert":
        """Create from dictionary."""
        return cls(
            alert_id=data["alert_id"],
            alert_type=data["alert_type"],
            severity=data["severity"],
            description=data["description"],
            detection_method=data["detection_method"],
            timestamp=data["timestamp"],
            related_event_ids=data.get("related_event_ids", []),
            recommended_action=data.get("recommended_action"),
            confidence=data.get("confidence"),
        )


class DetectorInterface(ABC):
    """Abstract base class for API security detectors."""
    
    @abstractmethod
    def detect(self, events: List[APIEvent]) -> List[SecurityAlert]:
        """Analyze a list of API events and return a list of security alerts.
        
        Args:
            events: List of API events to analyze (typically a time window).
            
        Returns:
            List of SecurityAlert objects (may be empty).
        """
        pass

    @property
    @abstractmethod
    def detector_name(self) -> str:
        """Human-readable name of the detector."""
        pass

    @property
    @abstractmethod
    def alert_type(self) -> str:
        """Type of alert this detector produces (e.g., 'scraping', 'token_misuse', 'bola')."""
        pass
